  function todayISO(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function formatDate(input,day=0,short=false){let d=new Date(input+'T12:00:00');if(Number.isNaN(+d))return '';d.setDate(d.getDate()+day);return `${d.getMonth()+1}/${d.getDate()} (${['일','월','화','수','목','금','토'][d.getDay()]})${short?'': ''}`;}
  function dateISO(input,day){let d=new Date(input+'T12:00:00');d.setDate(d.getDate()+day);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function formatKorean(input,day=0){let d=new Date(input+'T12:00:00');if(Number.isNaN(+d))return '';d.setDate(d.getDate()+day);return `${d.getMonth()+1}월 ${d.getDate()}일 ${['일','월','화','수','목','금','토'][d.getDay()]}요일`;}
  function placeList(day=state.day){if(!state.trip)return [];return state.trip.places.filter(p=>day===-1||p.day===day);}
