  function dayCards(day){const plans=plannedDay(day),candidates=candidatesDay(day);return `${plans.length?plans.map((p,j)=>placeCard(p,j,day)).join(''):'<div class="hint" style="padding:8px 0 16px">등록한 정식 일정이 없습니다.</div>'}${candidates.length?`<div class="candidate-title">📌 근처에 들러볼 후보 <span>${candidates.length}곳 · 이동 경로에서는 제외돼요</span></div>${candidates.map((p,j)=>placeCard(p,j,day)).join('')}`:''}`;}
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toastWrap').appendChild(el);setTimeout(()=>el.remove(),3600);}
  async function api(path,opts={}){let res;try{res=await fetch(path,{...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...opts.headers}});}catch{throw Error('서버에 연결할 수 없습니다. 인터넷 연결을 확인해주세요.');}let data={};try{data=await res.json();}catch{}if(!res.ok)throw Error(data.error||'요청에 실패했습니다.');return data;}
  function recentRead(){try{return JSON.parse(localStorage.getItem('moatrip_recent')||'[]').filter(x=>x&&/^[a-f0-9]{32}$/.test(x.id)).slice(0,14);}catch{return [];}}
  function saveRecent(trip){state.recent=recentRead().filter(x=>x.id!==trip.id);state.recent.unshift({id:trip.id,title:trip.title,destination:trip.destination,startDate:trip.startDate,dayCount:trip.dayCount});localStorage.setItem('moatrip_recent',JSON.stringify(state.recent.slice(0,14)));}
  async function loadTrip(id){try{const data=await api('/api/trips/'+id);setTrip(data.trip);return true;}catch(e){toast(e.message,true);return false;}}
  function setTrip(trip){const changed=state.trip?.id!==trip.id;state.trip=trip;saveRecent(trip);if(changed){state.day=0;state.destinationLookedUp='';state.selectedId=null;connectSSE(trip.id);history.replaceState(null,'',`/?trip=${encodeURIComponent(trip.id)}`);}else if(state.day>=trip.dayCount){state.day=0;}render(true);}
  function updateTrip(trip){if(!trip||state.trip?.id!==trip.id)return;if(trip.version<state.trip.version)return;state.trip=trip;saveRecent(trip);render(false);}
  async function mutate(path,method,body){if(state.busy)return null;state.busy=true;try{const data=await api(path,{method,body:body!==undefined?JSON.stringify(body):undefined});if(data.trip)updateTrip(data.trip);return data;}catch(e){toast(e.message,true);return null;}finally{state.busy=false;}}
  function connectSSE(id){if(state.eventSource){state.eventSource.close();state.eventSource=null;}if(typeof EventSource==='undefined')return;const es=new EventSource('/api/trips/'+id+'/events');state.eventSource=es;es.onopen=()=>connection(true);es.onmessage=()=>{};es.addEventListener('trip',ev=>{try{updateTrip(JSON.parse(ev.data));}catch{}});es.onerror=()=>connection(false);}
  function connection(on){const e=$('#connectionStatus');e.classList.toggle('online',on);e.querySelector('.online-text').textContent=on?'친구와 실시간 연결':'다시 연결 중';}
  function render(fit=false){if(!state.trip)return;const t=state.trip;$('#topTripName').textContent=t.title;$('#tripTitle').textContent=t.title;$('#tripMeta').innerHTML=`${icon('map-pin',14)} ${esc(t.destination||'여행지 미설정')} <span style="opacity:.4">·</span> ${esc(formatDate(t.startDate))} ~ ${esc(formatDate(t.startDate,t.dayCount-1))} <span style="opacity:.4">·</span> ${t.dayCount}일`;
    const tabs=Array.from({length:t.dayCount},(_,i)=>`<button class="day-tab ${state.day===i?'selected':''}" data-day="${i}" role="tab" aria-selected="${state.day===i}"><span>DAY ${i+1}</span><small>${esc(formatDate(t.startDate,i))}</small></button>`).join('');
    $('#dayTabs').innerHTML=tabs+`<button class="day-tab ${state.day===-1?'selected':''}" data-day="-1" role="tab" aria-selected="${state.day===-1}"><span>전체</span><small>ALL DAYS</small></button>`;
    $('#mobileMapDays').innerHTML=`<button type="button" data-map-day="-1" class="${state.day===-1?'active':''}">전체 보기</button>`+Array.from({length:t.dayCount},(_,i)=>`<button type="button" data-map-day="${i}" class="${state.day===i?'active':''}">DAY ${i+1}</button>`).join('');
    const all=state.day===-1;const places=placeList();$('#dayOverline').textContent=all?'ALL DAYS · COMPLETE ROUTE':`DAY ${String(state.day+1).padStart(2,'0')} · PLAN YOUR DAY`;$('#dayHeading').textContent=all?'전체 여행 한눈에 보기':`${formatKorean(t.startDate,state.day)}의 일정`;$('#daySubtitle').textContent=all?'각 날짜의 장소와 동선을 색깔별로 확인하세요.':'장소를 누르면 지도에서 위치를 확인할 수 있어요.';$('#dayCountBadge').textContent=`${places.length} places`;
    $('#mapTagTitle').textContent=all?'모든 여행 동선':`DAY ${state.day+1} 여행 지도`;$('#mapTagSub').textContent=all?`${t.dayCount}일 · 총 ${places.length}개 장소`:`${formatKorean(t.startDate,state.day)} · ${places.length}곳`;
    $('#mapEmptyHint').classList.toggle('hidden',places.length!==0);
    $('#itinerary').innerHTML=all?Array.from({length:t.dayCount},(_,i)=>{const ps=orderedDay(i);return `<div class="day-section-head"><span style="display:flex;align-items:center;gap:7px"><span style="display:inline-block;width:9px;height:9px;background:${colors[i%colors.length]};border-radius:100%"></span>DAY ${i+1} · ${esc(formatDate(t.startDate,i))} <span style="color:#a6adbb">${ps.length}곳</span></span><button data-day-go="${i}">이 날짜 보기</button></div>${dayCards(i)}`;}).join(''):(places.length?dayCards(state.day):`<div class="empty-plan"><div class="empty-illustration">${icon('camera',31)}</div><h3>스크린샷으로 일정을 만들어보세요</h3><p>블로그·지도 캡처와 짧은 메모로 장소를 찾고<br>시간 순으로 추가할 수 있어요.</p><button data-open-quick>사진으로 빠르게 추가 ${icon('plus',12)}</button></div>`);
    $('#addPlaceBtn').innerHTML=icon('plus')+(all?' 날짜 선택해서 장소 추가하기':' 장소 직접 검색하기')+' <span class="add-shortcut">＋</span>';
    renderMap(fit);
  }
  function placeCard(p,index,day){const c=categories[p.category]||'관광·기타';const candidate=p.kind==='candidate';const clr=pinColors[p.category]||pinColors.spot;return `<article class="place-card ${candidate?'candidate-card':''} ${state.selectedId===p.id?'focused':''}" draggable="${state.day!==-1}" data-card="${esc(p.id)}" data-card-day="${day}" tabindex="0"><div class="place-order ${candidate?'candidate-order':''}" style="background:${clr}19;color:${clr}">${candidate?'★':index+1}</div><div class="place-detail"><div class="place-line-1"><span class="place-name">${esc(p.name)}</span><span class="place-category"><span class="category-dot" style="background:${clr}"></span>${esc(c)}</span>${candidate?'<span class="candidate-tag">근처 후보</span>':''}</div><div class="place-address" title="${esc(p.address)}">${icon('map-pin',12)} ${esc(p.address||`${p.lat.toFixed(5)}, ${p.lng.toFixed(5)}`)}</div>${p.time?`<div class="place-time">${icon('clock',13)} ${esc(p.time)}${p.duration?' · '+p.duration+'분':''}</div>`:''}${p.note?`<div class="place-note">${esc(p.note)}</div>`:''}<div class="place-actions"><button class="tiny-action" data-maps-place="${esc(p.id)}">${icon('external-link',11)} 구글지도</button>${state.day===-1?'':`<button class="tiny-action" data-move="up" data-pid="${esc(p.id)}" aria-label="순서 올리기">${icon('arrow-up',11)}</button><button class="tiny-action" data-move="down" data-pid="${esc(p.id)}" aria-label="순서 내리기">${icon('arrow-down',11)}</button>`}<button class="tiny-action" data-edit="${esc(p.id)}">${icon('pencil',11)} 수정</button></div></div><button class="card-menu" data-edit="${esc(p.id)}" aria-label="${esc(p.name)} 수정">${icon('more',17)}</button></article>`;}
  function renderMap(fit=false){if(!state.map||!state.trip)return;clearOverlays();const days=state.day===-1?Array.from({length:state.trip.dayCount},(_,i)=>i):[state.day];let all=[];days.forEach(day=>{const ps=plannedDay(day);const wishes=state.showCandidates?candidatesDay(day):[];all=all.concat(ps,wishes);const clr=colors[day%colors.length];if(ps.length>1)drawLine(ps.map(p=>[p.lat,p.lng]),clr);ps.forEach((p,i)=>drawMarker(p,i+1,pinColors[p.category]||pinColors.spot));wishes.forEach((p)=>drawMarker(p,'★',pinColors[p.category]||pinColors.spot));});if(fit)fitMap();}
  function clearOverlays(){state.overlays.forEach(o=>{try{if(state.provider==='google')o.setMap(null);else state.map.removeLayer(o);}catch{}});state.overlays=[];state.markers.clear();}
  function drawLine(points,color){if(state.provider==='google'){const poly=new google.maps.Polyline({path:points.map(([lat,lng])=>({lat,lng})),geodesic:true,strokeColor:color,strokeOpacity:.75,strokeWeight:3,map:state.map});state.overlays.push(poly);}else{const poly=L.polyline(points,{color,weight:3,opacity:.86,dashArray:'7,9',lineCap:'round'}).addTo(state.map);state.overlays.push(poly);}}
  function drawMarker(p,index,color){const popup=`<div class="popup-content"><strong>📍 ${esc(p.name)}</strong><small>DAY ${p.day+1} · ${esc(categories[p.category]||'관광')} · ${p.kind==='candidate'?'근처 후보':esc(p.time||'시간 미정')}</small><button data-popup-focus="${esc(p.id)}">일정 보기</button></div>`;
    if(state.provider==='google'){
      const marker=new google.maps.Marker({position:{lat:p.lat,lng:p.lng},map:state.map,label:{text:String(index),color:p.kind==='candidate'?color:'white',fontWeight:'bold',fontSize:'12px'},title:p.name,icon:{path:google.maps.SymbolPath.CIRCLE,fillColor:p.kind==='candidate'?'#ffffff':color,fillOpacity:1,strokeColor:color,strokeWeight:3,scale:p.kind==='candidate'?13:17}});
      const info=new google.maps.InfoWindow({content:popup});marker.addListener('click',()=>{info.open({anchor:marker,map:state.map});state.selectedId=p.id;highlightCard();});state.overlays.push(marker);state.markers.set(p.id,{marker,info});
    } else {
      const marker=L.marker([p.lat,p.lng],{icon:L.divIcon({html:`<div class="numbered-pin ${p.kind==='candidate'?'candidate-pin':''}" style="--marker-color:${color}"><span>${index}</span></div>`,iconSize:[35,39],iconAnchor:[17,34],popupAnchor:[0,-33]})}).addTo(state.map).bindPopup(popup);
      marker.on('click',()=>{state.selectedId=p.id;highlightCard();});state.overlays.push(marker);state.markers.set(p.id,{marker});
    }
  }
  function highlightCard(){document.querySelectorAll('[data-card]').forEach(el=>el.classList.toggle('focused',el.dataset.card===state.selectedId));}
  function fitMap(){if(!state.map)return;const ps=placeList().filter(p=>p.kind!=='candidate'||state.showCandidates);if(!ps.length){destinationCenter();return;}if(state.provider==='google'){if(ps.length===1){state.map.setCenter({lat:ps[0].lat,lng:ps[0].lng});state.map.setZoom(13);}else{const b=new google.maps.LatLngBounds();ps.forEach(p=>b.extend({lat:p.lat,lng:p.lng}));state.map.fitBounds(b,75);}}else{state.map.invalidateSize();if(ps.length===1)state.map.setView([ps[0].lat,ps[0].lng],13);else state.map.fitBounds(ps.map(p=>[p.lat,p.lng]),{padding:[62,62],maxZoom:13,animate:false});}}
  async function destinationCenter(){if(!state.trip?.destination||state.destinationLookedUp===state.trip.id||placeList().length)return;state.destinationLookedUp=state.trip.id;try{const r=await api('/api/search?q='+encodeURIComponent(state.trip.destination));if(state.trip&&!placeList().length&&r.results?.[0]){const p=r.results[0];if(state.provider==='google'){state.map.setCenter({lat:p.lat,lng:p.lng});state.map.setZoom(10);}else state.map.setView([p.lat,p.lng],10);}}catch{}}
  function focusPlace(id){const p=state.trip?.places.find(x=>x.id===id);if(!p)return;if(state.day!==-1&&state.day!==p.day)state.day=p.day;state.selectedId=id;render(false);if(state.provider==='google'){state.map.panTo({lat:p.lat,lng:p.lng});state.map.setZoom(Math.max(state.map.getZoom()||12,13));state.markers.get(id)?.info?.open({map:state.map,anchor:state.markers.get(id).marker});}else{state.map.setView([p.lat,p.lng],Math.max(state.map.getZoom(),13));state.markers.get(id)?.marker.openPopup();}if(window.innerWidth<=850)mobileView('map');}
  // Raster OSM tiles already contain Chinese characters. A multilingual vector
  // basemap is required to change the actual map labels, not just our markers.
  // The primary style has Korean labels built in; an OpenFreeMap vector style
  // with Korean/English fallback is used if the primary server is unavailable.
  // The original OSM raster stays available until a replacement finishes loading.
  const KOREAN_MAP_STYLES = [
    {url:'https://styles.maptoolkit.org/summer-ko.json',provider:'Maptoolkit',attribution:'<a href="https://www.maptoolkit.com/copyright/" target="_blank" rel="noopener noreferrer">&copy; Maptoolkit</a> <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">&copy; OpenStreetMap</a>'},
    {url:'https://tiles.openfreemap.org/styles/liberty',provider:'OpenFreeMap',attribution:'<a href="https://openfreemap.org/" target="_blank" rel="noopener noreferrer">&copy; OpenFreeMap</a> <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">&copy; OpenStreetMap</a>'}
  ];
  function prioritizeKoreanVectorLabels(glMap){
    if(!glMap?.getStyle || !glMap.setLayoutProperty)return;
    for(const layer of glMap.getStyle().layers||[]){
      if(layer.type!=='symbol' || !layer.layout?.['text-field'])continue;
      // Preserve numeric house numbers, road shield codes and exit numbers.
      if(/(?:house.?number|address|road.?shield|route.?shield|exit.?number|junction|ref.?label)/i.test(layer.id))continue;
      try{
        glMap.setLayoutProperty(layer.id,'text-field',[
          'coalesce',
          ['get','name_ko'],['get','name:ko'],
          ['get','name_en'],['get','name:en'],
          ['get','name_int'],['get','name:latin'],
          ['get','name']
        ]);
      }catch(err){console.warn('일부 지도 레이블의 언어를 변경하지 못했습니다.',layer.id,err);}
    }
  }
  function installKoreanBasemap(raster){
    const source=$('#mapSource');
    const brand=$('#maptoolkitLogo');
    if(!window.maplibregl || !window.L?.maplibreGL){
      source.textContent='지도: 기본 지도 (한국어 지도 라이브러리를 불러오지 못함)';
      return;
    }
    const tryStyle=index=>{
      const style=KOREAN_MAP_STYLES[index];
      if(!style){source.textContent='지도: 기본 지도 (한국어 지도 서비스 연결 불가)';return;}
      let layer,glMap,settled=false,timer;
      const fail=error=>{
        if(settled)return;
        settled=true;
        clearTimeout(timer);
        console.warn('한국어 지도 서비스 연결 실패:',style.provider,error);
        try{if(layer&&state.map.hasLayer(layer))state.map.removeLayer(layer);}catch{}
        tryStyle(index+1);
      };
      try{
        layer=L.maplibreGL({style:style.url,attribution:style.attribution,maxZoom:19}).addTo(state.map);
        glMap=layer.getMaplibreMap();
        if(!glMap || typeof glMap.once!=='function')throw new Error('지도 렌더러 초기화 실패');
        timer=setTimeout(()=>fail(new Error('지도 스타일 로딩 시간 초과')),16000);
        glMap.once('load',()=>{
          if(settled)return;
          try{
            prioritizeKoreanVectorLabels(glMap);
            // Keep the newly loaded vector map; remove Chinese-labeled raster.
            if(state.map.hasLayer(raster))state.map.removeLayer(raster);
            settled=true;
            clearTimeout(timer);
            state.koreanLayer=layer;
            source.textContent='지도: 한국어 우선 · 일부 미번역 지명은 현지어';
            brand.hidden=style.provider!=='Maptoolkit';
            console.info('한국어 지도 준비 완료:',style.provider);
          }catch(err){fail(err);}
        });
        glMap.on('error',event=>{
          // On initial load, malformed/missing styles should trigger fallback.
          // A transient tile error after a successful load should not reset the map.
          if(!settled)fail(event?.error||new Error('지도 데이터를 가져오지 못함'));
        });
      }catch(err){fail(err);}
    };
    tryStyle(0);
  }
  async function initMap(){state.googleKey=(state.config.googleMapsKey||localStorage.getItem('moatrip_google_key')||'').trim();if(state.googleKey){try{await loadGoogle(state.googleKey);}catch(e){console.warn('Google 지도 초기화 실패, 기본 지도로 대체합니다.',e);toast('구글지도를 불러오지 못해 기본 지도를 표시합니다.',true);}}
    if(window.google?.maps&&state.googleKey){state.provider='google';state.map=new google.maps.Map($('#map'),{center:{lat:25.045,lng:121.55},zoom:10,streetViewControl:false,mapTypeControl:false,fullscreenControl:false,gestureHandling:'greedy'});state.map.addListener('click',e=>{if(state.mapPick)onMapPick(e.latLng.lat(),e.latLng.lng());});$('#mapSource').textContent='지도: Google Maps';}
    else if(window.L){state.provider='leaflet';state.map=L.map('map',{zoomControl:false}).setView([25.045,121.55],10);const raster=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(state.map);state.map.on('click',e=>{if(state.mapPick)onMapPick(e.latlng.lat,e.latlng.lng);});installKoreanBasemap(raster);}
    else{toast('지도 라이브러리를 불러오지 못했습니다. 인터넷 연결을 확인해주세요.',true);return;}
    renderMap(true);
  }
  function loadGoogle(key){return new Promise((resolve,reject)=>{const cb='moatripGoogleInit';const timeout=setTimeout(()=>{delete window[cb];reject(new Error('timeout'));},11000);window[cb]=()=>{clearTimeout(timeout);delete window[cb];resolve();};const s=document.createElement('script');s.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly&libraries=places&language=ko&loading=async&callback=${cb}`;s.async=true;s.onerror=()=>{clearTimeout(timeout);delete window[cb];reject(new Error('load error'));};document.head.appendChild(s);});}
  function mobileView(view){state.view=view;$('#workspace').classList.toggle('mobile-list',view==='list');$('#workspace').classList.toggle('mobile-map',view==='map');document.querySelectorAll('[data-mobile]').forEach(el=>el.classList.toggle('selected',el.dataset.mobile===view));if(view==='map'&&state.map){setTimeout(()=>{if(state.provider==='leaflet')state.map.invalidateSize();else google.maps.event.trigger(state.map,'resize');fitMap();},50);}}
