  function editTripModal(){const t=state.trip;if(!t)return;openModal(`<div class="modal-label">TRAVEL SETTINGS</div><h2 id="dialogTitle">여행 정보 수정</h2><p class="dialog-sub">여행 이름과 일정을 바꿀 수 있어요.</p><form id="editTripForm"><div class="form-field"><label for="etTitle">여행 이름 *</label><input id="etTitle" maxlength="100" required value="${esc(t.title)}" /></div><div class="form-field"><label for="etDestination">여행 도시 / 국가</label><input id="etDestination" maxlength="120" value="${esc(t.destination)}" /></div><div class="form-row"><div class="form-field"><label for="etStartDate">출발 날짜</label><input id="etStartDate" type="date" value="${esc(t.startDate)}" required /></div><div class="form-field"><label for="etDayCount">여행 기간</label><select id="etDayCount">${Array.from({length:30},(_,i)=>`<option value="${i+1}" ${i+1===t.dayCount?'selected':''}>${i+1}일 (${i}박 ${i+1}일)</option>`).join('')}</select></div></div><div class="form-field"><label for="etDescription">메모 (선택)</label><textarea id="etDescription" maxlength="800" placeholder="숙소, 항공편, 준비물 등을 적어주세요.">${esc(t.description)}</textarea></div><div class="modal-actions"><button type="button" class="secondary-btn" id="cancelEt">취소</button><button type="submit" class="primary-btn">수정 저장</button></div></form>`);$('#cancelEt').onclick=closeModal;$('#editTripForm').onsubmit=async e=>{e.preventDefault();const data=await mutate('/api/trips/'+t.id,'PATCH',{title:$('#etTitle').value,destination:$('#etDestination').value,startDate:$('#etStartDate').value,dayCount:Number($('#etDayCount').value),description:$('#etDescription').value});if(data){closeModal();toast('여행 정보가 저장됐어요.');}};}
